// Only signed-in people reach it; the person arrives as a parameter.
notes.MapPost("", CreateAsync).RequireUser()
    .WithName("createNote")
    .WithDescription("Saves a new note by the signed-in person and returns it.");

// Where signing in is optional, take EndgameUser? instead.
api.MapGet("greeting", (EndgameUser? user) =>
        user is null ? "Hello, visitor" : $"Hello, {user.DisplayName} ({user.Role ?? "end user"})")
    .WithName("getGreeting")
    .WithDescription("A greeting for whoever is using the app.");

// Anywhere else: IEndgameIdentity.
var canManage = identity.CurrentUser is { Kind: EndgameUserKind.Member, Role: "owner" or "admin" };

import { api, NotSignedInError, signInUrl } from "@endgame/appkit";

try {
  await api("notes", { method: "POST", body: { title } });
} catch (e) {
  if (e instanceof NotSignedInError) location.assign(e.signInUrl ?? signInUrl());
  else throw e;
}

api.MapGet("greeting", (EndgameUser user) => $"Hello, {user.DisplayName}")
    .WithName("getGreeting")
    .WithDescription("A greeting for the signed-in person.");
